WITH reference_value AS (SELECT MAX_BY(b.volume,b.bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` b JOIN `newzl`.`hsj_stock_code_info` s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='比亚迪' AND b.bizdate>=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' WEEK) AND b.bizdate<=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' DAY)), averages AS (SELECT mktcode,tgtcode,AVG(volume) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) GROUP BY mktcode,tgtcode) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN averages m ON m.mktcode=a.mktcode AND m.tgtcode=a.tgtcode CROSS JOIN reference_value r WHERE a.volume<r.value AND m.value>0;
